import re
body = thread['emails'][0]['body']
# Extract bullet lines with =>
lines = []
for ln in body.splitlines():
    if '=>' in ln:
        lines.append(ln.strip())
print('lines', lines)

pattern = re.compile(r'^[-\s]*(?P<name>.+?)\s*=>\s*(?P<day>\w+)\s*@\s*(?P<hour>\d{1,2}):(?P<minute>\d{2})\s*$', re.IGNORECASE)
meetings=[]
for ln in lines:
    m=pattern.match(ln)
    print('match', ln, bool(m))
    if m:
        meetings.append({
            'name': m.group('name').strip(),
            'day': m.group('day').lower(),
            'start_hour': int(m.group('hour')),
            'start_minute': int(m.group('minute'))
        })
print('meetings_parsed', meetings)

# subtract 10 minutes

def sub_minutes(hour, minute, delta=10):
    total = hour*60 + minute - delta
    # wrap into 0..1439
    total %= 24*60
    ah = total//60
    am = total%60
    return f"{ah:02d}:{am:02d}"

desired=[]
for mt in meetings:
    desired.append({
        'label': mt['name'],
        'repeat_days': [mt['day']],
        'time': sub_minutes(mt['start_hour'], mt['start_minute'], 10),
        'snooze_minutes': 10
    })
print('desired', desired)

# compare with existing alarms stored in all_alarms

def alarms_match(alarm, d):
    # repeat_days may be null
    if alarm.get('label') != d['label']:
        return False
    if alarm.get('time') != d['time']:
        return False
    if alarm.get('snooze_minutes') != float(d['snooze_minutes']) and alarm.get('snooze_minutes') != d['snooze_minutes']:
        return False
    rd = alarm.get('repeat_days')
    if not rd:
        return False
    # exact set match for day list
    return set([x.lower() for x in rd]) == set([x.lower() for x in d['repeat_days']])

existing_matches=[]
to_create=[]
for d in desired:
    match = None
    for a in all_alarms:
        if alarms_match(a,d):
            match=a
            break
    if match:
        existing_matches.append((d['label'], match.get('alarm_id')))
    else:
        to_create.append(d)

print('existing_matches', existing_matches)
print('to_create_count', len(to_create))
for d in to_create:
    print(d)

